package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.network.FriendlyByteBuf;import java.util.*;
public record DwfReply(int menu,long revision,int page,boolean more,long total,long capacity,int variants,int variantLimit,String status,long progress,int duration,String productName,long remaining,boolean continuous,boolean creative,List<Long>counts,List<String>recipes,List<String>details,List<Material>materials) implements net.minecraft.network.protocol.common.custom.CustomPacketPayload{
 public static final Type<DwfReply> TYPE=new Type<>(net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("sbwdroneconfig","dwfreply"));
 @Override public Type<DwfReply>type(){return TYPE;}
 public record Material(net.minecraft.world.item.ItemStack icon,String name,long available,long required){
  public Material{icon=icon.copy();if(!icon.isEmpty())icon.setCount(1);if(name.length()>160||available< -1||required<1)throw new IllegalArgumentException("Invalid material row");}
  @Override public boolean equals(Object other){return other instanceof Material m&&available==m.available&&required==m.required&&name.equals(m.name)&&net.minecraft.world.item.ItemStack.isSameItemSameComponents(icon,m.icon);}
  @Override public int hashCode(){return Objects.hash(name,available,required,icon.getItem());}
 }
 public DwfReply{counts=List.copyOf(counts);recipes=List.copyOf(recipes);details=List.copyOf(details);materials=List.copyOf(materials);if(materials.size()>64)throw new IllegalArgumentException("Too many material rows");}
 public static void encode(DwfReply m,FriendlyByteBuf b){b.writeVarInt(m.menu);b.writeVarLong(m.revision);b.writeVarInt(m.page);b.writeBoolean(m.more);b.writeVarLong(m.total);b.writeVarLong(m.capacity);b.writeVarInt(m.variants);b.writeVarInt(m.variantLimit);b.writeUtf(m.status,160);b.writeVarLong(m.progress);b.writeVarInt(m.duration);b.writeUtf(m.productName,160);b.writeVarLong(m.remaining);b.writeBoolean(m.continuous);b.writeBoolean(m.creative);b.writeVarInt(m.counts.size());for(long n:m.counts)b.writeVarLong(n);for(String r:m.recipes)b.writeUtf(r,160);b.writeVarInt(m.details.size());for(String d:m.details)b.writeUtf(d,160);b.writeVarInt(m.materials.size());for(var material:m.materials){net.minecraft.world.item.ItemStack.OPTIONAL_STREAM_CODEC.encode((net.minecraft.network.RegistryFriendlyByteBuf)b,material.icon());b.writeUtf(material.name(),160);b.writeVarLong(material.available());b.writeVarLong(material.required());}}
 public static DwfReply decode(FriendlyByteBuf b){int menu=b.readVarInt();long revision=b.readVarLong();int page=b.readVarInt();boolean more=b.readBoolean();long total=b.readVarLong(),capacity=b.readVarLong();int variants=b.readVarInt(),limit=b.readVarInt();String status=b.readUtf(160);long progress=b.readVarLong();int duration=b.readVarInt();String productName=b.readUtf(160);long remaining=b.readVarLong();boolean continuous=b.readBoolean(),creative=b.readBoolean();int size=b.readVarInt();if(size<0||size>45)throw new IllegalArgumentException("Invalid DWF page size");var counts=new ArrayList<Long>();var recipes=new ArrayList<String>();for(int i=0;i<size;i++)counts.add(b.readVarLong());for(int i=0;i<size;i++)recipes.add(b.readUtf(160));int n=b.readVarInt();if(n<0||n>64)throw new IllegalArgumentException("Invalid DWF details");var details=new ArrayList<String>();for(int i=0;i<n;i++)details.add(b.readUtf(160));int materialSize=b.readVarInt();if(materialSize<0||materialSize>64)throw new IllegalArgumentException("Invalid materials size");var materials=new ArrayList<Material>();for(int i=0;i<materialSize;i++)materials.add(new Material(net.minecraft.world.item.ItemStack.OPTIONAL_STREAM_CODEC.decode((net.minecraft.network.RegistryFriendlyByteBuf)b),b.readUtf(160),b.readVarLong(),b.readVarLong()));return new DwfReply(menu,revision,page,more,total,capacity,variants,limit,status,progress,duration,productName,remaining,continuous,creative,counts,recipes,details,materials);}
 public static void handle(DwfReply m,net.neoforged.neoforge.network.handling.IPayloadContext c){c.enqueueWork(()->{var player=c.player();if(player.containerMenu instanceof DwfMenu menu&&menu.containerId==m.menu())menu.view=m;});}
}
